changeSet.sql:
-- No job is queued while the existing ones are numbered.
lock table pipeline_jobs in exclusive mode;
create sequence pipeline_jobs_queue_seq as bigint;
alter table pipeline_jobs add column queue_seq bigint;
update pipeline_jobs j
   set queue_seq = o.n
  from (select id, row_number() over (order by created_at, id) as n from pipeline_jobs) o
 where j.id = o.id;
select setval('pipeline_jobs_queue_seq', coalesce((select max(queue_seq) from pipeline_jobs), 0) + 1, false);
alter sequence pipeline_jobs_queue_seq owned by pipeline_jobs.queue_seq;
alter table pipeline_jobs alter column queue_seq set default nextval('pipeline_jobs_queue_seq');
alter table pipeline_jobs alter column queue_seq set not null;
alter table pipeline_jobs add constraint ux_pipeline_jobs_queue_seq unique (queue_seq);
-- The pick-up query: due jobs of a stage, in priority order, then queue order.
drop index if exists idx_pipeline_jobs_pickup;
create index idx_pipeline_jobs_pickup on pipeline_jobs (stage, next_attempt_at, queue_seq)
    where status in ('READY', 'WAITING_RETRY');
-- Running jobs per entity and destination (the per-destination worker limit).
create index idx_pipeline_jobs_running_tenant on pipeline_jobs (tenant_id, destination_id)
    where status = 'RUNNING';

rollback.sql:
drop index if exists idx_pipeline_jobs_running_tenant;
drop index if exists idx_pipeline_jobs_pickup;
create index idx_pipeline_jobs_pickup on pipeline_jobs (stage, next_attempt_at, created_at)
    where status in ('READY', 'WAITING_RETRY');
alter table pipeline_jobs drop constraint if exists ux_pipeline_jobs_queue_seq;
alter table pipeline_jobs drop column if exists queue_seq;
drop sequence if exists pipeline_jobs_queue_seq;
